# Required area per month (months 1..4)
req = {1: 1500, 2: 1000, 3: 2000, 4: 1200}

# Cost per m^2 for a contract of length L months
cost = {1: 28, 2: 45, 3: 60, 4: 73}

months = [1, 2, 3, 4]

prob = pulp.LpProblem("Warehouse_Rental", pulp.LpMinimize)

# x[i][L] = area rented starting at month i for L months
x = {}
for i in months:
    for L in months:
        if i + L - 1 <= 4:
            x[(i, L)] = pulp.LpVariable(f"x_{i}_{L}", lowBound=0, cat="Continuous")

