prob += pulp.lpSum(cost[L] * x[(i, L)] for (i, L) in x)

# Constraints: area rented covering each month must meet requirement
for m in months:
    prob += pulp.lpSum(x[(i, L)] for (i, L) in x if i <= m <= i + L - 1) >= req[m]

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
